def left_aligned_fill_per_band(grid):
    """Each 3-row band fills leftwards from the first column that has any colored cell in that row"""
    h, w = len(grid), len(grid[0])
    result = [[grid[r][c] for c in range(w)] for r in range(h)]

    bands = {
        5: (0, 2),
        4: (3, 5),
        2: (6, 8),
        8: (9, 11)
    }

    for color, (band_start, band_end) in bands.items():
        for r in range(band_start, band_end + 1):
            cols_with_color = [c for c in range(w) if grid[r][c] == color]

            if cols_with_color:
                min_c = min(cols_with_color)
                # Fill from min_c to end of band width with this color
                band_width = w // 2  # Each band is roughly half-width
                for c in range(min_c, min(min_c + band_width, w)):
